wikidata_published_query_endpoint.query:
SELECT DISTINCT ?item ?name ?kana ?address ?mu ?corporate ?official WHERE {
  ?item wdt:P31 wd:Q845945 ; rdfs:label ?name ; wdt:P1814 ?kana .
  FILTER(LANG(?name)="ja")
  OPTIONAL { ?item wdt:P6375 ?address . FILTER(LANG(?address)="ja") }
  OPTIONAL { ?item wdt:P131 ?city . ?city rdfs:label ?mu . FILTER(LANG(?mu)="ja") }
  OPTIONAL { ?item wdt:P3225 ?corporate }
  OPTIONAL { ?item wdt:P856 ?official }
}
